// Verificar si sb_AYER.jsonl existe y tiene 0 resoluciones
const { execSync } = require('child_process');
const ayer = new Date();
ayer.setDate(ayer.getDate() - 1);
const fecha = ayer.toISOString().slice(0, 10);
const sbFile = `/mnt/c/users/hogar/tennis-analysis/backend/reports/shadow_book/sb_${fecha}.jsonl`;

let resultado = { fecha, sin_settle: false, n_picks: 0, n_settled: 0, archivo_existe: false };

try {
  const lines = execSync(`wc -l < ${sbFile}`, { encoding: 'utf8' }).trim();
  resultado.archivo_existe = true;
  resultado.n_picks = parseInt(lines) || 0;
  const settled = execSync(`grep -c '"resolucion"' ${sbFile} || echo 0`, { encoding: 'utf8' }).trim();
  resultado.n_settled = parseInt(settled) || 0;
  resultado.sin_settle = resultado.n_picks > 0 && resultado.n_settled === 0;
} catch (e) {
  resultado.archivo_existe = false;
  resultado.sin_settle = false;
}

return [{ json: resultado }];

